-- 901 v2 Supabase setup
create table if not exists public.class901_site(id bigint primary key default 1,subtitle text not null default '歡迎來到我們的青春基地。',hero_text text not null default '這裡收藏 901 的日常、笑聲、回憶，還有那些只有我們才懂的小故事。',quote_text text not null default '「下課只有十分鐘，\n但我們可以笑一整天。」',quote_cite text not null default '— 901',constraint class901_site_singleton check(id=1));
insert into public.class901_site(id) values(1) on conflict(id) do nothing;
create table if not exists public.class901_news(id bigint generated always as identity primary key,date_text text,title text not null,body text not null,icon text default '📌',sort_order bigint default 0,created_at timestamptz default now());
create table if not exists public.class901_members(id bigint generated always as identity primary key,name text not null,tag text,avatar text,bio text,sort_order bigint default 0,created_at timestamptz default now());
create table if not exists public.class901_events(id bigint generated always as identity primary key,event_date date,month_day text,title text not null,body text,location text,sort_order bigint default 0,created_at timestamptz default now());
create table if not exists public.class901_albums(id bigint generated always as identity primary key,album_date date,title text not null,description text,cover_emoji text default '📸',created_at timestamptz default now());
create table if not exists public.class901_photos(id bigint generated always as identity primary key,album_id bigint references public.class901_albums(id) on delete set null,storage_path text not null,public_url text not null,caption text,created_at timestamptz default now());
create table if not exists public.class901_capsules(id bigint generated always as identity primary key,name text not null,message text not null,created_at timestamptz default now());
alter table public.class901_site enable row level security;alter table public.class901_news enable row level security;alter table public.class901_members enable row level security;alter table public.class901_events enable row level security;alter table public.class901_albums enable row level security;alter table public.class901_photos enable row level security;alter table public.class901_capsules enable row level security;
grant usage on schema public to anon,authenticated;
grant select on public.class901_site,public.class901_news,public.class901_members,public.class901_events,public.class901_albums,public.class901_photos,public.class901_capsules to anon,authenticated;
grant insert,update,delete on public.class901_site,public.class901_news,public.class901_members,public.class901_events,public.class901_albums,public.class901_photos,public.class901_capsules to authenticated;
grant insert on public.class901_photos,public.class901_capsules to anon;
drop policy if exists p_site_r on public.class901_site;drop policy if exists p_site_w on public.class901_site;create policy p_site_r on public.class901_site for select to anon,authenticated using(true);create policy p_site_w on public.class901_site for all to authenticated using(true) with check(true);
drop policy if exists p_news_r on public.class901_news;drop policy if exists p_news_w on public.class901_news;create policy p_news_r on public.class901_news for select to anon,authenticated using(true);create policy p_news_w on public.class901_news for all to authenticated using(true) with check(true);
drop policy if exists p_mem_r on public.class901_members;drop policy if exists p_mem_w on public.class901_members;create policy p_mem_r on public.class901_members for select to anon,authenticated using(true);create policy p_mem_w on public.class901_members for all to authenticated using(true) with check(true);
drop policy if exists p_evt_r on public.class901_events;drop policy if exists p_evt_w on public.class901_events;create policy p_evt_r on public.class901_events for select to anon,authenticated using(true);create policy p_evt_w on public.class901_events for all to authenticated using(true) with check(true);
drop policy if exists p_alb_r on public.class901_albums;drop policy if exists p_alb_w on public.class901_albums;create policy p_alb_r on public.class901_albums for select to anon,authenticated using(true);create policy p_alb_w on public.class901_albums for all to authenticated using(true) with check(true);
drop policy if exists p_pho_r on public.class901_photos;drop policy if exists p_pho_i on public.class901_photos;drop policy if exists p_pho_w on public.class901_photos;create policy p_pho_r on public.class901_photos for select to anon,authenticated using(true);create policy p_pho_i on public.class901_photos for insert to anon,authenticated with check(true);create policy p_pho_w on public.class901_photos for all to authenticated using(true) with check(true);
drop policy if exists p_cap_r on public.class901_capsules;drop policy if exists p_cap_i on public.class901_capsules;drop policy if exists p_cap_u on public.class901_capsules;drop policy if exists p_cap_d on public.class901_capsules;create policy p_cap_r on public.class901_capsules for select to anon,authenticated using(true);create policy p_cap_i on public.class901_capsules for insert to anon,authenticated with check(char_length(name) between 1 and 40 and char_length(message) between 1 and 1000);create policy p_cap_u on public.class901_capsules for update to authenticated using(true) with check(true);create policy p_cap_d on public.class901_capsules for delete to authenticated using(true);
insert into storage.buckets(id,name,public) values('class-photos','class-photos',true) on conflict(id) do update set public=true;
drop policy if exists p_storage_r on storage.objects;drop policy if exists p_storage_i on storage.objects;drop policy if exists p_storage_d on storage.objects;
create policy p_storage_r on storage.objects for select to public using(bucket_id='class-photos');create policy p_storage_i on storage.objects for insert to anon,authenticated with check(bucket_id='class-photos');create policy p_storage_d on storage.objects for delete to authenticated using(bucket_id='class-photos');
insert into public.class901_news(date_text,title,body,icon,sort_order) select * from (values('2026 / 09 / 18','班級大掃除','記得帶好清潔工具，一起把 901 整理得漂漂亮亮！','📌',1),('COMING SOON','班級活動','下一個活動等你來決定，記得留意班群公告。','⭐',2),('REMINDER','作業小提醒','今天該交的作業不要忘記，901 加油！','💡',3)) v(date_text,title,body,icon,sort_order) where not exists(select 1 from public.class901_news);
insert into public.class901_members(name,tag,avatar,sort_order) select * from (values('小明','氣氛製造機','😎',1),('小美','筆記研究員','📚',2),('阿哲','體育戰神','🏃',3),('小涵','笑聲擔當','😂',4),('阿凱','午餐專家','🍱',5),('你的名字','待解鎖...','?',6)) v(name,tag,avatar,sort_order) where not exists(select 1 from public.class901_members);
insert into public.class901_events(event_date,month_day,title,body,location,sort_order) select * from (values('2026-09-18','09/18','班級大掃除','一起把 901 整理得漂漂亮亮！','901 教室',1),('2026-10-01','10/01','班級活動','下一個活動等你來決定。','校園',2)) v(event_date,month_day,title,body,location,sort_order) where not exists(select 1 from public.class901_events);
insert into public.class901_albums(album_date,title,description,cover_emoji) select * from (values('2026-09-01','開學日','901 新篇章正式開始','🏫'),('2026-09-15','那些爆笑瞬間','只有 901 懂的畫面','😂'),('2026-10-01','班級活動','一起留下更多回憶','🎉')) v(album_date,title,description,cover_emoji) where not exists(select 1 from public.class901_albums);
notify pgrst,'reload schema';